#include <algorithm>
#include <iostream>
#include <vector>
#include <random>
#include <stdexcept>
using namespace std;using ll=long long;using Poly=vector<ll>;using Rows=vector<int>;
void need(bool v,const char*s){if(!v)throw runtime_error(s);}void trim(Poly&p){while(p.size()>1&&!p.back())p.pop_back();}
Poly add(Poly a,const Poly&b,ll scale=1){a.resize(max(a.size(),b.size()));for(int i=0;i<(int)b.size();i++)a[i]+=scale*b[i];trim(a);return a;}Poly mul(const Poly&a,const Poly&b){Poly p(a.size()+b.size()-1);for(int i=0;i<(int)a.size();i++)for(int j=0;j<(int)b.size();j++)p[i+j]+=a[i]*b[j];trim(p);return p;}Poly power(Poly a,int k){Poly b={1};while(k--){b=mul(b,a);}return b;}Poly mon(int k){Poly p(k+1);p[k]=1;return p;}Poly shift(const Poly&p,int d){Poly out={0},pow={1};for(auto x:p){Poly a=pow;for(auto&v:a)v*=x;out=add(out,a);pow=mul(pow,{d,1});}return out;}ll val(const Poly&p,int x){ll z=0;for(auto i=p.rbegin();i!=p.rend();i++)z=z*x+*i;return z;}
vector<vector<ll>> endpaths(const Rows&a){int n=a.size(),M=1<<n;vector<vector<ll>>d(M,vector<ll>(n));for(int v=0;v<n;v++)d[1<<v][v]=1;for(int S=1;S<M;S++)for(int u=0;u<n;u++)if(d[S][u])for(int U=a[u]&~S;U;U&=U-1){int b=U&-U;d[S|b][__builtin_ctz((unsigned)b)]+=d[S][u];}return d;}
Poly bins(const Rows&a){int n=a.size(),M=1<<n;if(!n)return {1};auto d=endpaths(a);vector<ll>H(M);H[0]=1;for(int S=1;S<M;S++)for(auto x:d[S])H[S]+=x;vector<vector<ll>>P(M,vector<ll>(n+1));P[0][0]=1;for(int S=1;S<M;S++){int b=S&-S,R=S^b;for(int U=R;;U=(U-1)&R){int B=U|b,T=R^U;for(int k=0;k<n;k++)P[S][k+1]+=H[B]*P[T][k];if(!U)break;}}Poly out={0},fall={1};for(int k=0;k<=n;k++){Poly a=fall;for(auto&x:a)x*=P.back()[k];out=add(out,a);fall=mul(fall,{-k,1});}return out;}
Rows induced(const Rows&a,int S){vector<int>v;for(int i=0;i<(int)a.size();i++)if(S>>i&1)v.push_back(i);Rows b(v.size());for(int i=0;i<(int)v.size();i++)for(int j=0;j<(int)v.size();j++)if(a[v[i]]>>v[j]&1)b[i]|=1<<j;return b;}
Rows mirror(const Rows&S,int a,const Rows&T){int t=S.size(),u=T.size();Rows b(2*t+u);for(int i=0;i<t;i++)for(int j=0;j<t;j++){if(S[i]>>j&1){b[i]|=1<<j;b[t+j]|=1<<(t+i);}if(i==a&&j==a)b[i]|=1<<(t+j);else b[t+j]|=1<<i;}for(int i=0;i<u;i++){b[2*t+i]|=T[i]<<(2*t);for(int j=0;j<t;j++){b[t+j]|=1<<(2*t+i);b[2*t+i]|=1<<j;}}return b;}
Poly endpoint(const Rows&S,int a){auto d=endpaths(S);Poly E={0};int full=(1<<S.size())-1;for(int U=1;U<=full;U++)if(d[U][a]){Poly b=bins(induced(S,full^U));for(auto&x:b)x*=d[U][a];E=add(E,b);}return E;}
Poly apply(const Poly&B,const Poly&E,const Poly&f){Poly neg=E;for(int i=1;i<(int)neg.size();i+=2)neg[i]*=-1;return add(add(mul(mul(B,B),f),mul(mul({0,1},mul(E,E)),shift(f,1))),mul(mul({0,1},mul(neg,neg)),shift(f,-1)),-1);}
Rows tr(int n){Rows a(n);for(int i=0;i<n;i++)for(int j=i+1;j<n;j++)a[i]|=1<<j;return a;}
long long sides=0,contexts=0;
void check(const Rows&S,int a){auto B=bins(S),E=endpoint(S,a);Rows opp=S;for(int i=0;i<(int)S.size();i++)opp[i]^=((1<<S.size())-1)^(1<<i);auto d=endpaths(opp);ll e=d.back()[a];need(val(E,-1)==((S.size()+1)%2?-e:e),"endpoint reciprocity sign");for(const Rows&T:vector<Rows>{{}, {0},tr(2),tr(3),{2,4,1}}){Poly f=bins(T),actual=bins(mirror(S,a,T)),predicted=apply(B,E,f);need(actual==predicted,"full physical operator");need(all_of(actual.begin(),actual.end(),[](ll x){return x>=0;}),"physical coefficients");need(val(actual,1)==val(B,1)*val(B,1)*val(f,1)+val(E,1)*val(E,1)*val(f,2)-e*e*val(f,0),"three-point scalar");contexts++;}sides++;}
int main(){for(int n=1;n<=4;n++)for(int code=0;code<(1<<(n*(n-1)/2));code++){Rows S(n);int k=0;for(int i=0;i<n;i++)for(int j=i+1;j<n;j++,k++){bool f=code>>k&1;S[f?i:j]|=1<<(f?j:i);}for(int a=0;a<n;a++)check(S,a);}mt19937 rng(1971244);for(int c=0;c<16;c++){Rows S(5);for(int i=0;i<5;i++)for(int j=i+1;j<5;j++){bool f=rng()&1;S[f?i:j]|=1<<(f?j:i);}check(S,c%5);}cout<<"PASS side_contexts "<<sides<<" physical_substitutions "<<contexts<<"\n";
for(int k=1;k<=4;k++){Rows S=tr(k+2);S[0]^=1<<(k+1);S.back()|=1;Poly B=bins(S),E=endpoint(S,0),expectedB=add(mon(k+2),mul({0,1},add(power({1,1},k),power({-1,1},k),-1)));Poly expectedE=add(mon(k+1),power({1,1},k));need(B==expectedB&&E==expectedE,"explicit side profiles");Poly closed=add(add(mon(2*k+4),mul(mul({2},mon(k+2)),add(power({1,1},k+1),power({-1,1},k+1),-1))),mul({0,1},add(add(power({1,1},2*k+1),power({-1,1},2*k+1)),mul({0,2},power({-1,0,1},k)),-1)));Poly Q=bins(mirror(S,0,{}));need(Q==closed,"quadratic full-bin profile");cout<<"FAMILY "<<k<<" B";for(auto x:Q)cout<<" "<<x;cout<<" H "<<val(Q,1)<<" B2 "<<val(Q,2)<<"\n";if(k==3){need(val(Q,1)==161&&val(Q,2)==10304&&val(Q,3)==216009,"ratio hostile profile");need(val(Q,2)==161*64&&val(Q,3)!=161*729,"same ratio different full profile");}}
}
